import re
from decimal import Decimal

# All arithmetic here is exact and independent of the caller's decimal context:
# Decimal construction, comparison and as_tuple() never round, and amounts are
# handled as integer cents once validated.

MAX_AMOUNT_CENTS = 100_000_000  # 1000000.00

_MAX_AMOUNT = Decimal("1000000.00")
_AMOUNT_STRING = re.compile(r"[+-]?[0-9]+(?:\.[0-9]+)?")


def parse_cents(value):
    """Validate an amount and return it as an exact integer number of cents."""
    if isinstance(value, bool):
        raise ValueError("bool is not a valid amount")
    if isinstance(value, int):
        if value <= 0 or value > 1000000:
            raise ValueError("amount must be positive and at most 1000000.00")
        return value * 100
    if isinstance(value, str):
        if _AMOUNT_STRING.fullmatch(value) is None:
            raise ValueError("amount string does not match the accepted grammar")
        dec = Decimal(value)
    elif isinstance(value, Decimal):
        dec = Decimal(value)  # exact copy, independent of subclass overrides
    else:
        raise ValueError(f"unsupported amount type: {type(value).__name__}")
    return _decimal_to_cents(dec)


def _decimal_to_cents(dec):
    if not dec.is_finite():
        raise ValueError("amount must be finite")
    if dec <= 0:
        raise ValueError("amount must be positive")
    if dec > _MAX_AMOUNT:
        raise ValueError("amount must not exceed 1000000.00")
    _, digits, exponent = dec.as_tuple()
    # Strip trailing zeros so exactness is decided on the reduced coefficient.
    # dec > 0 guarantees a nonzero digit, so this loop terminates in range.
    coefficient = list(digits)
    while coefficient[-1] == 0:
        coefficient.pop()
        exponent += 1
    # A reduced coefficient has no trailing zero, so a negative exponent below
    # -2 always leaves a nonzero fractional cent.
    if exponent < -2:
        raise ValueError("amount is not exactly representable in cents")
    # Range checks above bound the coefficient to at most 9 digits here.
    return int("".join(map(str, coefficient))) * 10 ** (exponent + 2)


def cents_to_amount(cents):
    """Return an exact Decimal with exponent -2 for a non-negative cent count."""
    return Decimal(f"{cents // 100}.{cents % 100:02d}")


def parse_amount(value):
    return cents_to_amount(parse_cents(value))


def format_amount(value):
    return format(value, ".2f")
EOF
