from .money import MAX_AMOUNT_CENTS, cents_to_amount, format_amount, parse_cents


def make_invoice(amounts):
    if not isinstance(amounts, list):
        raise ValueError("amounts must be a list")
    total_cents = 0
    for item in amounts:
        total_cents += parse_cents(item)
    if total_cents > MAX_AMOUNT_CENTS:
        raise ValueError("total must not exceed 1000000.00")
    return {"total": format_amount(cents_to_amount(total_cents)), "count": len(amounts)}
EOF
